// A real first expedition, separate from the combat practice state.
function guildJourney(){if(!p?.tutorial?.completed)return null;if(!p.guildJourney){if(campaign().rank!==1||campaign().questDone.filter(id=>id.startsWith('hunt:')).length>1)return null;p.guildJourney={reported:campaign().questDone.includes('hunt:r0e0'),crafted:false,equipped:false,complete:false,recipe:''};}return p.guildJourney;}
function guildJourneyStep(){const j=guildJourney();if(!j||j.complete)return null;const q=campaign().contract;if(!j.reported)return !q?'accept':q.killed?'report':'hunt';if(!j.crafted)return 'craft';if(!j.equipped)return 'equip';return 'next';}
const GUILD_JOURNEY_TEXT={accept:['依頼を受けよう','おすすめの討伐依頼を受注します。指定された敵だけが討伐数に数えられます。'],hunt:['討伐して素材を拾おう','指定の敵を倒し、落ちた素材を調べる操作で回収。目標達成前の帰還・敗北は依頼失敗です。'],report:['村で依頼を報告しよう','目標達成！落ちた素材を回収してから帰還し、報告するとゴールドとランクXPを受け取れます。'],craft:['集めた素材で装備を作ろう','工房で装備を選び、必要な素材を確認します。複数の敵の素材が必要です。足りない分は自由探索で集めて帰還できます。'],equip:['作った装備を身につけよう','製作結果の「比較・装備する」から装備します。鞄に入れただけでは強くなりません。'],next:['次の依頼へ出発しよう','新しい装備で次の依頼を受注しましょう。依頼を報告してXPをためると、新しい依頼と昇格試験が解放されます。']};
function guildJourneyPrimary(){const step=guildJourneyStep();if(step==='accept'||step==='next'){guildAdvancedBoard=false;showVillage();return;}if(step==='hunt'){if(villageOpen)departRegion(guildQuest(campaign().contract.id).region);else closePanel();return;}if(step==='report'){if(villageOpen)claimContract();else returnVillage();return;}if(step==='craft'){if(!villageOpen){if(campaign().contract&&!campaign().contract.killed)closePanel();else returnVillage();return;}forgeCatalogSelected='rank1_0';showForge();return;}if(step==='equip')panel('inventory');}
function showGuildJourney(){const step=guildJourneyStep();if(!step)return showGameTips(5);const info=GUILD_JOURNEY_TEXT[step];worldMenu('はじめての冒険','<div class="journey-route">依頼 → 討伐・回収 → 報告 → 製作・装備 → 次の依頼</div><h3>'+info[0]+'</h3><p>'+info[1]+'</p>'+(step==='craft'?'<h4>最初の武器の例：'+gearEscape(FORGE_RECIPES[0].name)+'</h4>'+Object.entries(FORGE_RECIPES[0].cost).map(([id,n])=>materialTile(id,n)).join('')+(villageOpen?'<button onclick="departRegion(0)">不足素材を草原で集める</button>':''):'')+'<button onclick="guildJourneyPrimary()">'+({accept:'依頼掲示板へ',hunt:villageOpen?'討伐へ出発':'討伐に戻る',report:villageOpen?'報告する':'村へ帰還',craft:villageOpen?'工房で製作する':campaign().contract&&!campaign().contract.killed?'受注中の討伐を続ける':'村へ帰還して工房へ',equip:'装備を開く',next:'次の依頼を選ぶ'}[step])+'</button><button onclick="closePanel()">冒険に戻る</button>','guildJourney');menuFocusElement($('card').querySelector('.panel-body button')||$('card').querySelector('button'));}
function guildJourneyBanner(){const step=guildJourneyStep();if(!step||!paused||!['village','forgeRecipes','inventory'].includes(menuSurface)||$('guildJourneyBanner')||(menuSurface==='inventory'&&loadoutRoute.target))return;const info=GUILD_JOURNEY_TEXT[step],box=document.createElement('aside');box.id='guildJourneyBanner';box.className='guild-journey-banner';box.innerHTML='<b>はじめての冒険 · '+info[0]+'</b><button onclick="showGuildJourney()" aria-label="冒険の進め方">? 進め方</button>';($('card').querySelector('.panel-body')||$('card')).prepend(box);}
const journeyVillageBase=showVillage;showVillage=(...args)=>{const result=journeyVillageBase(...args);guildJourneyBanner();return result;};
const journeyForgeBase=showForge;showForge=(...args)=>{const result=journeyForgeBase(...args);guildJourneyBanner();return result;};
const journeyPanelBase=panel;panel=(...args)=>{const result=journeyPanelBase(...args);guildJourneyBanner();return result;};
const journeyStopBase=tutorialStop;tutorialStop=(complete=false)=>{const result=journeyStopBase(complete);if(complete&&guildJourneyStep())showGuildJourney();return result;};
function journeyTransactionAction(action,after){const base=worldTransaction;worldTransaction=change=>base(()=>{change();after();});try{return action();}finally{worldTransaction=base;}}
const journeyClaimBase=claimContract;claimContract=(...args)=>journeyTransactionAction(()=>journeyClaimBase(...args),()=>{const j=guildJourney();if(j)j.reported=true;});
const journeyCraftBase=craftForgeRecipe;craftForgeRecipe=id=>journeyTransactionAction(()=>journeyCraftBase(id),()=>{const j=guildJourney();if(j&&j.reported){j.crafted=true;j.recipe=id;}});
const journeyEquipBase=equip;equip=index=>{const item=p.bag[index],baseSave=save;save=(...args)=>{const j=guildJourney(),before=j?.equipped;if(j?.crafted&&item?.recipeId===j.recipe&&p[item.slot]===item)j.equipped=true;const result=baseSave(...args);if(result===false&&j)j.equipped=before;return result;};try{return journeyEquipBase(index);}finally{save=baseSave;}};
const journeyAcceptBase=acceptGuildQuest;acceptGuildQuest=id=>journeyTransactionAction(()=>journeyAcceptBase(id),()=>{const j=guildJourney();if(j?.equipped)j.complete=true;});
const journeyValidateBase=validateSave;validateSave=data=>{const out=journeyValidateBase(data),j=data.p.guildJourney;if(j!==undefined){if(!j||['reported','crafted','equipped','complete'].some(k=>typeof j[k]!=='boolean')||typeof j.recipe!=='string'||j.recipe&&!FORGE_RECIPES.some(r=>r.id===j.recipe)||j.crafted&&!j.reported||j.equipped&&!j.crafted||j.complete&&!j.equipped)throw Error('冒険ガイドの記録が不正です');out.p.guildJourney={reported:j.reported,crafted:j.crafted,equipped:j.equipped,complete:j.complete,recipe:j.recipe};}return out;};
document.body.insertAdjacentHTML('beforeend','<aside id="guildJourneyHud" hidden></aside>');let journeyHudKey='';const journeyHudBase=drawHud;drawHud=()=>{journeyHudBase();const step=started?guildJourneyStep():null,hud=$('guildJourneyHud');hud.hidden=!step||paused||dead||tutorialState().active;if(hud.hidden)return;const q=campaign().contract,key=step+':'+(q?.progress||0);if(key!==journeyHudKey){journeyHudKey=key;hud.innerHTML='<b>'+GUILD_JOURNEY_TEXT[step][0]+'</b><span>'+(step==='hunt'?'討伐 '+(q?.progress||0)+' / '+(q?.required||0)+' · 落ちた素材も回収':step==='report'?'回収 → 帰還 → 報告':GUILD_JOURNEY_TEXT[step][1])+'</span><button onclick="showGuildJourney()">? 進め方</button>';}};
const journeyPadBase=padMenu;padMenu=(g,l,r,dt)=>{if(menuSurface==='guildJourney'&&(padEdge(g,'back')||padEdge(g,'pause'))){closePanel();return;}return journeyPadBase(g,l,r,dt);};
